-- FuturePath: expand to the 25 subjects listed in JAMB's 2026 UTME training manual.
-- Topic titles are a structured study map, not a verbatim reproduction of JAMB's syllabus.
on conflict (slug) do update set name=excluded.name, description=excluded.description, sort_order=excluded.sort_order;

on conflict (subject_id,slug) do update set title=excluded.title, description=excluded.description, sort_order=excluded.sort_order;
